sys_script_client.script:
function onLoad() {

    var allFields = g_form.getEditableFields();

    allFields.forEach(function(field) {
        g_form.setReadOnly(field, true);
    });

    var cat = g_form.getValue('category');
    if (cat == '2')
        g_form.setLabelOf('contactpersontyp_authorized_person', 'ContactPersonTyp - Principal Particulars List');
    else if (cat == '3')
        g_form.setLabelOf('contactpersontyp_authorized_person', 'ContactPersonTyp - BENE_OWNER List');
}
